import{_ as n,l as t,o as a,c as r,v as i,p as c,x as l,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"内核配置与编译","description":"","frontmatter":{"title":"内核配置与编译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-config-build.md","filePath":"cs/kernel-config-build.md","lastUpdated":1789023840000}'),f={name:"cs/kernel-config-build.md"};function u(h,e,m,_,g,k){const o=t("Mermaid");return a(),r("div",null,[e[1]||(e[1]=i('<h1 id="内核配置与编译" tabindex="-1">内核配置与编译 <a class="header-anchor" href="#内核配置与编译" aria-label="Permalink to &quot;内核配置与编译&quot;">​</a></h1><div class="epigraph"><p>Kconfig 决定哪些子系统编进内核或模块；.config 是构建输入，决定 [PREEMPT_RT](/cs/preempt-rt)、[KPTI](/cs/kpti-os)、调试选项是否存在。</p><footer>—— 据 Linux kbuild/Kconfig 文档；[cmdline](/cs/kernel-cmdline) 为运行时对照</footer></div><p><a href="/cs/livepatch">livepatch</a> 假定有匹配的二进制。<a href="/cs/kernel-hardening">加固</a> 是一组 CONFIG。缺口是 <strong>配置与编译</strong>：不是发行版包管理百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>make menuconfig</code>：三态 y/m/n。缺口：依赖与 select；localmodconfig；调试 on 则性能与大小变。本课不把全部符号当词典。</p><p><span class="marginnote">发行版提供预置 config。自编译要匹配 gcc 与 ABI——下一课 kABI。对象是构建系统。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>.config → kbuild 编 vmlinux/modules → 安装 + initramfs。对照 <a href="/cs/systemd-units">systemd</a>：用户态构建另一套。对照 DT：DTB 可独立于内核镜像。对照 ASan：<code>CONFIG_KASAN</code> 是开发配置。</p>',8)),(a(),c(p,null,{default:l(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KC%5B%22Kconfig%22%5D%20--%3E%20CFG%5B%22.config%22%5D%0A%20%20CFG%20--%3E%20KB%5B%22kbuild%22%5D%0A%20%20KB%20--%3E%20IMG%5B%22vmlinux%20%E4%B8%8E%E6%A8%A1%E5%9D%97%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kconfig 把内核变成可裁剪的产品族，使嵌入式与服务器分享源码。错误的 n 会让驱动不存在，表现为 udev 无节点。不要写成编译原理课。与 <a href="/cs/eas-scheduling">EAS</a>：无 CONFIG 则无该调度。</p><p>模块与内建的取舍影响启动与攻击面。</p><p>实现上：localmodconfig 按当前已加载模块裁剪，换硬件要重配。DEBUG_INFO 让 vmlinux 巨大但 perf 才好用。发行版 config 是产品选择，不是「完整内核」。 读法上只引用<a href="/cs/livepatch">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>内核配置与编译</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有交叉编译工具链。不保证 reproducable build 的每一步。下一课加载后的兼容：kABI 与模块签名。</p><p>版本字段会变，课序钉的是机制对象「内核配置与编译」，不是某一主线内核的结构体名。 后课默认：功能由 .config 决定。模块 ABI 与签名，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kconfig 生成 .config，kbuild 产出内核与模块。</li><li>调试与加固选项改变二进制。</li><li>kABI 与模块签名是下一课。</li><li>出处：kbuild；Kconfig；内核 README。</li></ul>',11))])}const T=n(f,[["render",u]]);export{A as __pageData,T as default};
